@register_source("list")
class ListSource(BaseSource):

    def __init__(
        self,
        items,
        get_items=None,
        base_path=".",
        keep_original=True,
        **kwargs,
    ):
        self.items = items
        self.get_items = get_items
        self.base_path = base_path
        self.keep_original = keep_original
        self.kwargs = kwargs

    def load(self):

        if not self.items:
            raise ValueError("`items` cannot be empty.")

        first = self.items[0]

        # List of paths
        if isinstance(first, (str, Path)):
            records = [{"image": str(x)} for x in self.items]
            get_items = {"image": "image"}

        # List of dict-like records
        elif isinstance(first, dict):
            records = [dict(x) for x in self.items]
            get_items = self.get_items

        else:
            raise TypeError(
                "`items` must be a list of paths or dictionaries."
            )

        return DictSource(
            records,
            get_items=get_items,
            base_path=self.base_path,
            keep_original=self.keep_original,
            **self.kwargs,
        ).load()

