@register_source("callable")
class CallableSource(BaseSource):

    @delegates(DictSource.__init__)
    def __init__(
        self,
        items_fn,
        target_fn=None,
        x_keys="image",
        y_keys="label",
        **kwargs,
    ):
        self.items_fn = items_fn
        self.target_fn = target_fn
        self.x_keys = x_keys
        self.y_keys = y_keys
        self.kwargs = kwargs

    def load(self):

        items = list(self.items_fn())

        first = items[0]

        # Case 1: items already dictionaries
        if isinstance(first, dict):

            records = items
            if self.target_fn:
                 records = [dict(row, **{self.y_keys: self.target_fn(row[self.x_keys])}) for row in records]

        # Case 2: items are inputs only (paths, ids, etc.)
        else:

            records = []

            for x in items:

                row = {
                    self.x_keys: x
                }

                if self.target_fn:
                    row[self.y_keys] = self.target_fn(x)

                records.append(row)

        source = DictSource(
            records,
            x_keys=self.x_keys,
            y_keys=self.y_keys,
            **self.kwargs,
        )

        return source.load()

